import {formatDate, humanizeEventDueDate, formatDateDiff} from '../util/utils.js';
import OffersView from './offers-view.js';
import AbstractView from '../framework/view/abstract-view.js';

const DATE_FORMAT = 'MMM D';
const TIME_FORMAT = 'HH:mm';

function createEventTemplate(event, allOffers, destination) {
  const {type, dateFrom, dateTo, basePrice, isFavorite} = event;

  const destinationName = destination?.name || 'Unknown';

  const date = formatDate(dateFrom);
  const humanizeDate = humanizeEventDueDate(dateFrom, DATE_FORMAT);

  const timeStart = formatDate(dateFrom, {withTime: true});
  const humanizeTimeStart = humanizeEventDueDate(dateFrom, TIME_FORMAT);

  const timeEnd = formatDate(dateTo, {withTime: true});
  const humanizeTimeEnd = humanizeEventDueDate(dateTo, TIME_FORMAT);

  const duration = formatDateDiff(timeStart, timeEnd);

  const offersView = new OffersView({event, offers: allOffers});
  const offersTemplate = offersView.template;

  const favoriteButtonClass = isFavorite ? 'event__favorite-btn--active' : '';
  const favoriteButtonText = isFavorite ? 'Event favorite' : 'Add to favorite';

  return (
    `<li class="trip-events__item">
      <div class="event">
        <time class="event__date" datetime=${date}>${humanizeDate}</time>
        <div class="event__type">
          <img class="event__type-icon" width="42" height="42" src="img/icons/${type}.png" alt="Event type icon">
        </div>
        <h3 class="event__title">${type} ${destinationName}</h3>
        <div class="event__schedule">
          <p class="event__time">
            <time class="event__start-time" datetime=${timeStart}>${humanizeTimeStart}</time>
            &mdash;
            <time class="event__end-time" datetime=${timeEnd}>${humanizeTimeEnd}</time>
          </p>
          <p class="event__duration">${duration}</p>
        </div>
        <p class="event__price">
          &euro;&nbsp;<span class="event__price-value">${basePrice}</span>
        </p>
        <h4 class="visually-hidden">Offers:</h4>
        <ul class="event__selected-offers">
          ${offersTemplate}
        </ul>
        <button class="event__favorite-btn ${favoriteButtonClass}" type="button">
          <span class="visually-hidden">${favoriteButtonText}</span>
          <svg class="event__favorite-icon" width="28" height="28" viewBox="0 0 28 28">
            <path d="M14 21l-8.22899 4.3262 1.57159-9.1631L.685209 9.67376 9.8855 8.33688 14 0l4.1145 8.33688 9.2003 1.33688-6.6574 6.48934 1.5716 9.1631L14 21z"/>
          </svg>
        </button>
        <button class="event__rollup-btn" type="button">
          <span class="visually-hidden">Open event</span>
        </button>
      </div>
    </li>`
  );
}

export default class EventView extends AbstractView {
  #event = null;
  #offers = null;
  #destination = null;
  #handleRollupClick = null;
  #handleFavoriteClick = null;

  constructor({event, offers, destination, onRollupClick, onFavoriteClick}) {
    super();
    this.#event = event;
    this.#offers = offers || [];
    this.#destination = destination || { name: 'Unknown' };
    this.#handleRollupClick = onRollupClick;
    this.#handleFavoriteClick = onFavoriteClick;

    this.#restoreHandlers();
  }

  get template() {
    return createEventTemplate(this.#event, this.#offers, this.#destination);
  }

  #restoreHandlers() {
    const rollupBtn = this.element.querySelector('.event__rollup-btn');
    if (rollupBtn) {
      rollupBtn.addEventListener('click', this.#rollupClickHandler);
    }

    const favoriteBtn = this.element.querySelector('.event__favorite-btn');
    if (favoriteBtn) {
      favoriteBtn.addEventListener('click', this.#favoriteClickHandler);
    }
  }

  #rollupClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleRollupClick?.();
  };

  #favoriteClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleFavoriteClick?.();
  };
}
